#!/usr/bin/env node
// Regenerates references/ from the Swift Evolution feed, the compiler's Features.def,
// and swift.org's release list. Node 18+, no dependencies.
//
// Usage: node scripts/sync.mjs [--check] [--cache <dir>] [--no-prune] [--force-prune]
//   --check        exit 1 if any generated file would change; write nothing (CI)
//   --cache <dir>  read sources from <dir> if present, else fetch and save them there
//   --no-prune     keep generated files that no longer apply
//   --force-prune  allow deleting more than 10% of generated files in one run

import { mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const REFS = join(ROOT, 'skills', 'swift-evolution', 'references');
// Hand-written files under skills/swift-evolution/references/. sync.mjs never writes or deletes these.
const HANDWRITTEN = ['toolchain-detection.md'];
const MARK = '> Generated by scripts/sync.mjs';

const FEED = 'https://download.swift.org/swift-evolution/v1/evolution.json';
const PROPOSALS = 'https://github.com/swiftlang/swift-evolution/blob/main/proposals/';
const RELEASES_PATH = '_data/builds/swift_releases.yml';
const FEATURES_PATH = 'include/swift/Basic/Features.def';
const AVAILABILITY_PATH = 'utils/availability-macros.def';
const raw = (repo, ref, path) => `https://raw.githubusercontent.com/swiftlang/${repo}/${ref}/${path}`;

const args = process.argv.slice(2);
const has = (f) => args.includes(f);
const cacheDir = has('--cache') ? args[args.indexOf('--cache') + 1] : null;
const known = ['--check', '--cache', '--no-prune', '--force-prune'];
const unknown = args.filter((a, i) => !known.includes(a) && args[i - 1] !== '--cache');
if (unknown.length || (has('--cache') && !cacheDir)) die(`usage: sync.mjs [--check] [--cache <dir>] [--no-prune] [--force-prune]`);

function die(msg) {
  console.error(`sync: ${msg}`);
  process.exit(2);
}

async function get(url, cacheName) {
  const file = cacheDir && join(cacheDir, cacheName.replace(/[^\w.-]/g, '_'));
  if (file) {
    try { return await readFile(file, 'utf8'); } catch {}
  }
  const headers = { 'User-Agent': 'swift-evolution-skill-sync' };
  if (url.startsWith('https://api.github.com/') && process.env.GITHUB_TOKEN) {
    headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;
  }
  const res = await fetch(url, { headers });
  if (!res.ok) die(`${url}: HTTP ${res.status}`);
  const text = await res.text();
  if (file) {
    await mkdir(cacheDir, { recursive: true });
    await writeFile(file, text);
  }
  return text;
}

// The last commit that touched `path`, so the stamp only changes when the file does.
async function lastCommit(repo, path) {
  const url = `https://api.github.com/repos/swiftlang/${repo}/commits?path=${path}&per_page=1`;
  const sha = JSON.parse(await get(url, `last-commit-${repo}-${path}`))[0]?.sha;
  if (!sha) die(`no commit found for swiftlang/${repo}/${path}`);
  return sha;
}

function cmpVersion(a, b) {
  const x = a.split('.').map(Number), y = b.split('.').map(Number);
  for (let i = 0; i < Math.max(x.length, y.length); i++) {
    const d = (x[i] ?? 0) - (y[i] ?? 0);
    if (d) return d;
  }
  return 0;
}

const seNum = (id) => Number(id.slice(3));
const byId = (a, b) => seNum(a.id) - seNum(b.id);

// swift_releases.yml: a top-level list of `- name: "X"` entries with two-space-indented scalar keys.
function parseReleases(yml) {
  const out = [];
  for (const line of yml.split(/\r?\n/)) {
    let m = line.match(/^- name:\s*"?([^"]+?)"?\s*$/);
    if (m) { out.push({ name: m[1] }); continue; }
    m = line.match(/^  (tag|date|xcode):\s*"?(.+?)"?\s*$/);
    if (m && out.length) out.at(-1)[m[1]] = m[2];
  }
  if (!out.length || out.some((r) => !r.tag || !r.date)) die(`could not parse ${RELEASES_PATH}`);
  return out.sort((a, b) => cmpVersion(a.name, b.name));
}

function parseFeatures(def) {
  const out = new Map();
  const re = /^(MIGRATABLE_)?UPCOMING_FEATURE\((\w+),\s*(\d+),\s*LanguageMode::(\w+)\)/gm;
  for (const m of def.matchAll(re)) {
    const n = Number(m[3]);
    out.set(m[2], { flag: m[2], se: n ? `SE-${String(n).padStart(4, '0')}` : null, mode: m[4], migratable: !!m[1] });
  }
  if (!out.size) die(`no UPCOMING_FEATURE entries found in ${FEATURES_PATH}`);
  return out;
}

const modeName = (m) => (m === 'future' ? 'not on by default in any language mode yet' : `on by default in Swift ${m.replace(/^v/, '')} language mode`);
const link = (p) => `${PROPOSALS}${p.link}`;
const row = (cells) => `| ${cells.join(' | ')} |`;

// ---- fetch ----

const feed = JSON.parse(await get(FEED, 'evolution.json'));
if (String(feed.schemaVersion ?? '').split('.')[0] !== '1') {
  die(`unsupported evolution.json schemaVersion ${feed.schemaVersion}; update scripts/sync.mjs before syncing`);
}
const releasesSha = await lastCommit('swift-org-website', RELEASES_PATH);
const releases = parseReleases(await get(raw('swift-org-website', releasesSha, RELEASES_PATH), `swift_releases-${releasesSha}.yml`));
const latest = releases.at(-1);
const tagFeatures = parseFeatures(await get(raw('swift', latest.tag, FEATURES_PATH), `Features-${latest.tag}.def`));
const mainSha = await lastCommit('swift', FEATURES_PATH);
const mainFeatures = parseFeatures(await get(raw('swift', mainSha, FEATURES_PATH), `Features-${mainSha}.def`));
// Swift runtime version -> Apple OS releases that ship it, e.g. "6.4" -> "anyAppleOS 27.0". 9999 = unreleased.
const appleOS = new Map();
for (const m of (await get(raw('swift', latest.tag, AVAILABILITY_PATH), `availability-${latest.tag}.def`))
  .matchAll(/^SwiftStdlib (\d+\.\d+(?:\.\d+)?):(.+)$/gm)) {
  if (!m[2].includes('9999')) appleOS.set(m[1], m[2].trim());
}
if (!appleOS.size) die(`no SwiftStdlib entries found in ${AVAILABILITY_PATH}`);

// ---- render ----

const proposals = [...feed.proposals].sort(byId);
const byIdMap = new Map(proposals.map((p) => [p.id, p]));
const released = (v) => v && v !== 'Next';
const releaseFor = (v) => releases.find((r) => r.name === v || r.name === `${v}.0`);
const feedSrc = `${FEED} at swift-evolution commit ${feed.commit}`;
const header = (src) => `${MARK} from ${src}. Do not edit.\n\n`;
const files = new Map();

// proposals/<file>.md: full text of everything implemented since FULL_TEXT_FROM, so agents can read
// API shapes and back-deployment notes offline.
// The 6.0 floor keeps this to about 110 files; lower it if older releases need the detail.
const FULL_TEXT_FROM = '6.0';
const withText = proposals.filter((p) => p.status.state === 'implemented' && released(p.status.version) &&
  cmpVersion(p.status.version, FULL_TEXT_FROM) >= 0);
for (let i = 0; i < withText.length; i += 8) {
  await Promise.all(withText.slice(i, i + 8).map(async (p) => {
    const text = await get(raw('swift-evolution', feed.commit, `proposals/${p.link}`), `proposal-${p.link}-${p.sha}`);
    files.set(`proposals/${p.link}`, header(`${PROPOSALS}${p.link} at swift-evolution commit ${feed.commit}`) +
      text.replace(/\r\n/g, '\n').trim() + '\n');
  }));
}

function entry(p, extra = []) {
  const flag = p.upcomingFeatureFlag?.flag;
  const meta = [`[proposal](${link(p)})`, ...extra];
  if (files.has(`proposals/${p.link}`)) meta.push(`[full text](../proposals/${p.link})`);
  if (flag) meta.push(`upcoming feature flag \`${flag}\``);
  return `### ${p.id}: ${p.title.trim()}\n\n${p.summary.trim()}\n\n${meta.join(' | ')}\n`;
}

// versions/<X.Y>.md
const versions = new Map();
for (const p of proposals) {
  if (p.status.state === 'implemented' && released(p.status.version)) {
    if (!versions.has(p.status.version)) versions.set(p.status.version, []);
    versions.get(p.status.version).push(p);
  }
}
const versionList = [...versions.keys()].sort(cmpVersion).reverse();
for (const v of versionList) {
  const ps = versions.get(v);
  const r = releaseFor(v);
  const when = (r ? `Released ${r.date} as \`${r.tag}\`${r.xcode ? ` (${r.xcode})` : ''}.` : 'Release date not listed on swift.org.') +
    (appleOS.has(v) ? ` On Apple platforms its standard library and runtime ship with ${appleOS.get(v)}.` : '');
  files.set(`versions/${v}.md`, header(feedSrc) +
    `# Swift ${v}\n\n${when} ${ps.length} proposal${ps.length === 1 ? '' : 's'} implemented in this version; ` +
    `each needs Swift ${v} or newer.\n\n` + ps.map((p) => entry(p)).join('\n'));
}

// in-flight.md
const STATES = [
  ['Next', 'Implemented on main, not in any release yet (`Next`)'],
  ['accepted', 'Accepted, not implemented in a release'],
  ['previewing', 'Previewing (Standard Library Preview package only, not the standard library)'],
  ['activeReview', 'In review'],
  ['returnedForRevision', 'Returned for revision'],
  ['rejected', 'Rejected'],
  ['withdrawn', 'Withdrawn'],
];
const pending = proposals.filter((p) => !(p.status.state === 'implemented' && released(p.status.version)) && !(p.status.state === 'implemented' && !p.status.version));
const stateOf = (p) => (p.status.version === 'Next' ? 'Next' : p.status.state);
const seen = new Set(STATES.map(([s]) => s));
for (const s of [...new Set(pending.map(stateOf))].sort()) if (!seen.has(s)) STATES.push([s, s]);
let inflight = header(feedSrc) + '# Not available in any Swift release\n\nNothing in this file can be used with a released toolchain.\n';
for (const [state, title] of STATES) {
  const ps = pending.filter((p) => stateOf(p) === state);
  if (!ps.length) continue;
  const brief = ['returnedForRevision', 'rejected', 'withdrawn'].includes(state);
  inflight += `\n## ${title} (${ps.length})\n\n`;
  inflight += brief
    ? ps.map((p) => `- [${p.id}](${link(p)}): ${p.title.trim()}`).join('\n') + '\n'
    : ps.map((p) => entry(p, state === 'activeReview' && p.status.start ? [`review ${p.status.start.slice(0, 10)} to ${p.status.end?.slice(0, 10) ?? '?'}`] : [])).join('\n');
}
files.set('in-flight.md', inflight);

// upcoming-feature-flags.md
const feedVersion = (se) => byIdMap.get(se)?.status.version;
let flags = header(`${FEATURES_PATH} at \`${latest.tag}\` and main, joined with ${feedSrc}`) +
  `# Upcoming feature flags (as of Swift ${latest.name})\n\n` +
  'Enable a flag with `.enableUpcomingFeature("Name")` in a target\'s `swiftSettings`, or `-enable-upcoming-feature Name`. ' +
  'Flags marked migratable also accept `Name:migrate` to apply fix-its (SE-0486, Swift 6.2).\n';
const modes = [...new Set([...tagFeatures.values()].map((f) => f.mode))].sort((a, b) => (a === 'future') - (b === 'future') || a.localeCompare(b));
for (const mode of modes) {
  const fs = [...tagFeatures.values()].filter((f) => f.mode === mode).sort((a, b) => (a.se ? seNum(a.se) : 0) - (b.se ? seNum(b.se) : 0));
  flags += `\n## ${modeName(mode)[0].toUpperCase()}${modeName(mode).slice(1)} (${fs.length})\n\n`;
  flags += row(['Flag', 'Proposal', 'Proposal implemented in', 'Migratable']) + '\n' + row(['---', '---', '---', '---']) + '\n';
  flags += fs.map((f) => row([`\`${f.flag}\``, f.se ? `[${f.se}](${link(byIdMap.get(f.se) ?? { link: '' })})` : '-', feedVersion(f.se) ? `Swift ${feedVersion(f.se)}` : '-', f.migratable ? 'yes' : 'no'])).join('\n') + '\n';
}
const mainDiff = [];
for (const [name, f] of mainFeatures) {
  const t = tagFeatures.get(name);
  if (!t) mainDiff.push(`- \`${name}\`${f.se ? ` (${f.se})` : ''}: new on main, ${modeName(f.mode)}`);
  else if (t.mode !== f.mode) mainDiff.push(`- \`${name}\`${f.se ? ` (${f.se})` : ''}: ${modeName(t.mode)} in ${latest.tag}; ${modeName(f.mode)} on main`);
}
for (const name of tagFeatures.keys()) if (!mainFeatures.has(name)) mainDiff.push(`- \`${name}\`: removed on main`);
// Stamp main's commit only when it differs, so unrelated Features.def edits don't churn this file.
flags += `\n## Changes on main, not in ${latest.tag}\n\n` +
  (mainDiff.length ? `As of swiftlang/swift ${mainSha}:\n\n${mainDiff.sort().join('\n')}` : 'None.') + '\n';
const feedOnly = proposals.filter((p) => p.upcomingFeatureFlag && !tagFeatures.has(p.upcomingFeatureFlag.flag));
if (feedOnly.length) {
  flags += `\n## In the feed but not in ${latest.tag}\n\n` +
    feedOnly.map((p) => `- \`${p.upcomingFeatureFlag.flag}\` ([${p.id}](${link(p)}), ${p.status.state}${p.status.version ? ` ${p.status.version}` : ''})`).join('\n') + '\n';
}
files.set('upcoming-feature-flags.md', flags);

// releases.md
files.set('releases.md', header(`swiftlang/swift-org-website ${RELEASES_PATH} at ${releasesSha} and swiftlang/swift ${AVAILABILITY_PATH} at \`${latest.tag}\``) +
  '# Swift releases, Xcode versions and Apple OS runtimes\n\n' +
  '## Apple OS releases that ship each Swift runtime\n\n' +
  'A standard library or concurrency API added in Swift X.Y needs these OS versions unless its proposal says it back-deploys. ' +
  'In `@available` and `#available`, list the platforms (for example `macOS 27, iOS 27, *`).\n\n' +
  row(['Swift runtime', 'Apple OS']) + '\n' + row(['---', '---']) + '\n' +
  [...appleOS].sort((a, b) => cmpVersion(b[0], a[0])).map(([v, os]) => row([v, os])).join('\n') + '\n\n' +
  '## Releases\n\n' +
  row(['Swift', 'Released', 'Tag', 'Xcode']) + '\n' + row(['---', '---', '---', '---']) + '\n' +
  [...releases].reverse().map((r) => row([r.name, r.date, `\`${r.tag}\``, r.xcode ?? '-'])).join('\n') + '\n');

// lookup.md
const implemented = proposals.filter((p) => p.status.state === 'implemented');
const noVersion = implemented.filter((p) => !p.status.version);
const nextCount = proposals.filter((p) => p.status.version === 'Next').length;
files.set('lookup.md', header(feedSrc) +
  '# Swift Evolution lookup\n\n' +
  `Latest Swift release: **${latest.name}** (\`${latest.tag}\`, ${latest.date}${latest.xcode ? `, ${latest.xcode}` : ''}). ` +
  `The feed lists ${proposals.length} proposals; ${implemented.length - nextCount} are in a release.\n\n` +
  row(['Swift', 'Released', 'Xcode', 'Proposals', 'File']) + '\n' + row(['---', '---', '---', '---', '---']) + '\n' +
  row(['unreleased', '-', '-', `${pending.length} (${nextCount} on main)`, '[in-flight.md](in-flight.md)']) + '\n' +
  versionList.map((v) => {
    const r = releaseFor(v);
    return row([v, r?.date ?? '-', r?.xcode ?? '-', String(versions.get(v).length), `[versions/${v}.md](versions/${v}.md)`]);
  }).join('\n') + '\n\n' +
  '- [upcoming-feature-flags.md](upcoming-feature-flags.md): upcoming feature flags and the language mode that turns each on\n' +
  '- [releases.md](releases.md): every Swift release with its date, tag and Xcode version\n' +
  `- \`proposals/\`: full text of every proposal implemented since Swift ${FULL_TEXT_FROM}, linked from each version entry\n` +
  (noVersion.length ? `\nImplemented, but the feed records no version: ${noVersion.map((p) => p.id).join(', ')}.\n` : ''));

// ---- write / check / prune ----

async function listGenerated(dir, prefix = '') {
  const out = [];
  for (const e of await readdir(dir, { withFileTypes: true }).catch(() => [])) {
    const rel = prefix + e.name;
    if (e.isDirectory()) out.push(...await listGenerated(join(dir, e.name), `${rel}/`));
    else if (!HANDWRITTEN.includes(rel) && (await readFile(join(dir, e.name), 'utf8')).startsWith(MARK)) out.push(rel);
  }
  return out;
}

const existing = await listGenerated(REFS);
const changed = [];
// The header stamps a commit; a file whose body is unchanged keeps its old stamp,
// so an upstream commit only rewrites the files it actually affects.
const body = (s) => s.slice(s.indexOf('\n') + 1);
for (const [rel, content] of files) {
  if (HANDWRITTEN.includes(rel)) die(`refusing to generate hand-written file ${rel}`);
  const cur = await readFile(join(REFS, rel), 'utf8').then((s) => s.replace(/\r\n/g, '\n'), () => null);
  if (cur !== null && !cur.startsWith(MARK)) die(`${rel} exists and is not generated; refusing to overwrite`);
  if (cur === null || body(cur) !== body(content)) changed.push(rel);
}
const stale = has('--no-prune') ? [] : existing.filter((rel) => !files.has(rel));
if (stale.length > existing.length * 0.1 && !has('--force-prune')) {
  die(`would delete ${stale.length} of ${existing.length} generated files (over 10%): ${stale.join(', ')}. Re-run with --force-prune if that is intended.`);
}

// README.md shows the same stamp as lookup.md between <!-- sync:stamp --> markers; the rest of README is hand-written.
const lookupNow = changed.includes('lookup.md') ? files.get('lookup.md') : await readFile(join(REFS, 'lookup.md'), 'utf8');
const stampSha = lookupNow.match(/swift-evolution commit ([0-9a-f]{40})/)[1];
const STAMP = /<!-- sync:stamp -->[\s\S]*?<!-- \/sync:stamp -->/;
const stamp = `<!-- sync:stamp -->Synced from Swift Evolution [\`${stampSha.slice(0, 7)}\`](https://github.com/swiftlang/swift-evolution/commit/${stampSha}), ` +
  `latest release: Swift ${latest.name} (${latest.date})<!-- /sync:stamp -->`;
const readmePath = join(ROOT, 'README.md');
const readme = await readFile(readmePath, 'utf8').catch(() => null);
const readmeNew = readme && STAMP.test(readme) ? readme.replace(STAMP, stamp) : readme;

if (has('--check')) {
  for (const rel of changed) console.log(`would update ${rel}`);
  for (const rel of stale) console.log(`would delete ${rel}`);
  if (readmeNew !== readme) console.log('would update the README.md stamp');
  if (changed.length || stale.length || readmeNew !== readme) process.exit(1);
  console.log(`references are up to date with swift-evolution ${feed.commit.slice(0, 7)}`);
} else {
  for (const rel of changed) {
    await mkdir(dirname(join(REFS, rel)), { recursive: true });
    await writeFile(join(REFS, rel), files.get(rel));
  }
  for (const rel of stale) await rm(join(REFS, rel));
  if (readmeNew !== readme) await writeFile(readmePath, readmeNew);
  console.log(`swift-evolution ${feed.commit.slice(0, 7)}: ${changed.length} updated, ${stale.length} deleted, ${files.size - changed.length} unchanged`);
}
